}

static void compile_store(Compiler *c, const char *name) {
    int slot = resolve_local(c, name);
    if (slot >= 0) {
        if (c->locals[slot].is_boxed) emit(c, BC_STORE_BOX_LOCAL, slot, NULL);
        else emit(c, BC_STORE_LOCAL, slot, NULL);
        return;
    }
    int cap = resolve_capture(c, name);
    if (cap >= 0) { emit(c, BC_STORE_CAPTURE, cap, NULL); return; }
    emit(c, BC_STORE_GLOBAL, 0, strdup(name));
}

static void compile_load(Compiler *c, const char *name) {
    int slot = resolve_local(c, name);
    if (slot >= 0) {
        if (c->locals[slot].is_boxed) emit(c, BC_LOAD_BOX_LOCAL, slot, NULL);
        else emit(c, BC_LOAD_LOCAL, slot, NULL);
        return;
    }
    int cap = resolve_capture(c, name);
    if (cap >= 0) { emit(c, BC_LOAD_CAPTURE, cap, NULL); return; }
    emit(c, BC_LOAD_GLOBAL, 0, strdup(name));
}

